def fill_periods(apps, schema_editor):
    """Standard seasons and holidays for the existing settings; the old single "snow" effect turns the decoration
    on (with its dates kept as a one-off winter period on top of the list)."""
    from core.season import add_default_periods
    SiteSettings = apps.get_model("core", "SiteSettings")
    SeasonPeriod = apps.get_model("core", "SeasonPeriod")
    for s in SiteSettings.objects.all():
        add_default_periods(s, SeasonPeriod)
        if s.season_effect == "snow":
            s.season_enabled = True
            s.save(update_fields=["season_enabled"])
            if s.season_from and s.season_to:
                SeasonPeriod.objects.create(setting=s, sort_order=-1, effect="winter", yearly=False,
                                            date_from=s.season_from, date_to=s.season_to)


